-- 0030 — the business registration form, as the Registrar actually wants it.
--
-- The form shipped in 0028 was a reasonable guess. This is the real thing,
-- taken point for point from the sheet that gets handed in: the house number
-- and landmark, the street, the district, the city, the region and the box
-- number are each their own line on that sheet, there are three proposed
-- business names rather than two, and the purpose of the business is three
-- statements rather than one paragraph. Every one of them was missing.
--
-- The other entity types get what only they need — a partnership its partners
-- and their shares, a company limited by shares its stated capital, directors,
-- shareholders, secretary and auditor, a company limited by guarantee its
-- objects and council. Those ride on the variant, so a sole proprietor is
-- never shown a question about share capital.
--
-- Scoped to the rows 0028 seeded, by id. A product an administrator has since
-- deleted is not recreated, and nothing else in the catalogue is touched.

UPDATE "DataService" SET "fields" = '[{"key": "applicant_name", "label": "Applicant full name", "type": "text", "required": true, "hint": "Exactly as it appears on the Ghana Card", "options": [], "half": false}, {"key": "ghana_card_number", "label": "Ghana Card number", "type": "text", "required": true, "hint": "GHA-123456789-0", "options": [], "half": true}, {"key": "date_of_birth", "label": "Date of birth", "type": "date", "required": false, "hint": "", "options": [], "half": true}, {"key": "occupation", "label": "Occupation", "type": "text", "required": false, "hint": "", "options": [], "half": true}, {"key": "tin_number", "label": "TIN", "type": "text", "required": false, "hint": "Leave blank if you do not have one yet", "options": [], "half": true}, {"key": "applicant_phone", "label": "Phone number", "type": "phone", "required": true, "hint": "", "options": [], "half": true}, {"key": "applicant_phone_2", "label": "Alternate phone number", "type": "phone", "required": false, "hint": "", "options": [], "half": true}, {"key": "applicant_email", "label": "Email address", "type": "email", "required": true, "hint": "", "options": [], "half": true}, {"key": "house_number", "label": "House number", "type": "text", "required": false, "hint": "e.g. PLT/2-Abuakwa", "options": [], "half": true}, {"key": "landmark", "label": "Landmark", "type": "text", "required": false, "hint": "The nearest well-known place", "options": [], "half": true}, {"key": "street_name", "label": "Street name", "type": "text", "required": false, "hint": "", "options": [], "half": true}, {"key": "digital_address", "label": "Ghana Post GPS address", "type": "text", "required": false, "hint": "e.g. AH-1123-4341", "options": [], "half": true}, {"key": "city", "label": "City / town", "type": "text", "required": true, "hint": "", "options": [], "half": true}, {"key": "district", "label": "District", "type": "text", "required": true, "hint": "", "options": [], "half": true}, {"key": "region", "label": "Region", "type": "select", "required": true, "hint": "", "options": ["Ahafo", "Ashanti", "Bono", "Bono East", "Central", "Eastern", "Greater Accra", "North East", "Northern", "Oti", "Savannah", "Upper East", "Upper West", "Volta", "Western", "Western North"], "half": true}, {"key": "postal_address", "label": "Postal address", "type": "text", "required": false, "hint": "e.g. P. O. Box YB 80, Asuoyeboa", "options": [], "half": true}, {"key": "business_name_1", "label": "Business name — first choice", "type": "text", "required": true, "hint": "", "options": [], "half": false}, {"key": "business_name_2", "label": "Business name — second choice", "type": "text", "required": false, "hint": "Filed if the first is unavailable", "options": [], "half": false}, {"key": "business_name_3", "label": "Business name — third choice", "type": "text", "required": false, "hint": "", "options": [], "half": false}, {"key": "purpose_1", "label": "Purpose of the business — first", "type": "text", "required": true, "hint": "e.g. Hospital supplies and consumables", "options": [], "half": false}, {"key": "purpose_2", "label": "Purpose of the business — second", "type": "text", "required": false, "hint": "", "options": [], "half": false}, {"key": "purpose_3", "label": "Purpose of the business — third", "type": "text", "required": false, "hint": "", "options": [], "half": false}, {"key": "business_address", "label": "Business address", "type": "text", "required": false, "hint": "Leave blank if it is the same as the address above", "options": [], "half": false}, {"key": "notes", "label": "Anything else we should know", "type": "textarea", "required": false, "hint": "", "options": [], "half": false}, {"key": "id_front", "label": "Ghana Card — front", "type": "file", "required": true, "hint": "", "options": [], "half": false}, {"key": "id_back", "label": "Ghana Card — back", "type": "file", "required": true, "hint": "", "options": [], "half": false}, {"key": "passport_photo", "label": "Passport photograph", "type": "file", "required": true, "hint": "", "options": [], "half": false}]', "updatedAt" = CURRENT_TIMESTAMP
  WHERE "id" = 'svc_business_registration';

UPDATE "DataServiceVariant" SET "fields" = '[]', "updatedAt" = CURRENT_TIMESTAMP
  WHERE "id" = 'svcv_br_sole';

UPDATE "DataServiceVariant" SET "fields" = '[{"key": "partner_count", "label": "Number of partners", "type": "number", "required": true, "hint": "", "options": [], "half": true}, {"key": "partnership_deed", "label": "Is a partnership deed ready?", "type": "select", "required": false, "hint": "", "options": ["Yes", "No — please prepare one"], "half": true}, {"key": "partners", "label": "Partners — full name, Ghana Card number and share", "type": "textarea", "required": true, "hint": "One partner per line", "options": [], "half": false}, {"key": "partner_ids", "label": "Partners'' Ghana Cards", "type": "file", "required": false, "hint": "One file with every partner''s card, front and back", "options": [], "half": false}]', "updatedAt" = CURRENT_TIMESTAMP
  WHERE "id" = 'svcv_br_partnership';

UPDATE "DataServiceVariant" SET "fields" = '[{"key": "stated_capital", "label": "Stated capital (GHS)", "type": "number", "required": true, "hint": "", "options": [], "half": true}, {"key": "shares_issued", "label": "Number of shares issued", "type": "number", "required": true, "hint": "", "options": [], "half": true}, {"key": "directors", "label": "Directors — full name, Ghana Card number and address", "type": "textarea", "required": true, "hint": "At least two directors, one per line", "options": [], "half": false}, {"key": "shareholders", "label": "Shareholders and their shareholding", "type": "textarea", "required": true, "hint": "One shareholder per line, with the number of shares each holds", "options": [], "half": false}, {"key": "company_secretary", "label": "Company secretary", "type": "text", "required": false, "hint": "", "options": [], "half": true}, {"key": "secretary_id_number", "label": "Company secretary''s Ghana Card number", "type": "text", "required": false, "hint": "", "options": [], "half": true}, {"key": "auditor", "label": "Auditor", "type": "text", "required": false, "hint": "", "options": [], "half": true}, {"key": "beneficial_owners", "label": "Beneficial owners", "type": "textarea", "required": false, "hint": "Anyone holding more than 5%, if different from the shareholders above", "options": [], "half": false}, {"key": "director_ids", "label": "Directors'' Ghana Cards", "type": "file", "required": false, "hint": "", "options": [], "half": false}, {"key": "auditor_consent", "label": "Auditor''s consent letter", "type": "file", "required": false, "hint": "", "options": [], "half": false}]', "updatedAt" = CURRENT_TIMESTAMP
  WHERE "id" = 'svcv_br_limited';

UPDATE "DataServiceVariant" SET "fields" = '[{"key": "objects", "label": "Objects of the company", "type": "textarea", "required": true, "hint": "What the organisation exists to do", "options": [], "half": false}, {"key": "council_count", "label": "Number of council members", "type": "number", "required": false, "hint": "", "options": [], "half": true}, {"key": "council_members", "label": "Executive council members", "type": "textarea", "required": true, "hint": "One member per line, with the office each holds", "options": [], "half": false}, {"key": "council_ids", "label": "Council members'' Ghana Cards", "type": "file", "required": false, "hint": "", "options": [], "half": false}]', "updatedAt" = CURRENT_TIMESTAMP
  WHERE "id" = 'svcv_br_guarantee';

